let detailPhotos=[];
let descriptionBlocks=[];
window.__sosDetailPhotos=detailPhotos;
window.__sosDescriptionBlocks=descriptionBlocks;
const detailFieldsRoot=document.querySelector('.product-detail-fields');
if(detailFieldsRoot){
  const shortDescription=document.querySelector('#product-form [name="description"]')?.closest('label');
  if(shortDescription)shortDescription.hidden=true;
  const fullLabel=detailFieldsRoot.querySelector('[name="longDescription"]')?.closest('label');
  if(fullLabel)fullLabel.firstChild.textContent='Descrição do produto';
  detailFieldsRoot.insertAdjacentHTML('beforeend','<label class="span-two" hidden>Imagens antigas da descrição<input type="file" accept="image/png,image/jpeg,image/webp" multiple id="detail-gallery-upload"><div id="detail-gallery-preview" class="gallery-preview"></div></label><div class="span-two description-block-editor"><div class="description-block-head"><strong>Blocos da descrição</strong><button type="button" class="button outline" id="add-description-block">Adicionar bloco</button></div><p class="field-help">Cada bloco pode ter texto, imagem, os dois ou apenas um deles. Escolha qual lado deve aparecer primeiro.</p><div id="description-blocks-list"></div></div>');
}
function renderDetailPhotos(){window.__sosDetailPhotos=detailPhotos;const box=document.querySelector('#detail-gallery-preview');if(!box)return;box.innerHTML=detailPhotos.map((url,i)=>`<div class="gallery-thumb"><img src="${esc(url)}" alt="Imagem da descrição ${i+1}"><span>Imagem ${i+1}</span><button type="button" data-detail-photo-remove="${i}">Remover</button></div>`).join('')}
function renderDescriptionBlocks(){window.__sosDescriptionBlocks=descriptionBlocks;const box=document.querySelector('#description-blocks-list');if(!box)return;box.innerHTML=descriptionBlocks.map((block,i)=>`<article class="description-block-row"><div class="description-block-row-head"><strong>Bloco ${i+1}</strong><button type="button" class="danger" data-description-block-remove="${i}">Remover</button></div><label>Texto<textarea data-description-text="${i}" rows="4" placeholder="Escreva o conteúdo deste bloco"></textarea></label><label>Imagem<input data-description-image="${i}" value="${esc(block.image||'')}" placeholder="URL da imagem ou envie um arquivo"><input type="file" accept="image/png,image/jpeg,image/webp" data-description-upload="${i}"></label><label>Composição<select data-description-layout="${i}"><option value="text-image">Texto à esquerda, imagem à direita</option><option value="image-text">Imagem à esquerda, texto à direita</option><option value="text">Somente texto</option><option value="image">Somente imagem</option></select></label><div class="description-block-preview">${block.image?`<img src="${esc(block.image)}" alt="Prévia do bloco ${i+1}">`:''}</div></article>`).join('');descriptionBlocks.forEach((block,i)=>{const text=box.querySelector(`[data-description-text="${i}"]`);const layout=box.querySelector(`[data-description-layout="${i}"]`);if(text)text.value=block.text||'';if(layout)layout.value=block.layout||'text-image'})}
const baseFillProductDetailFields=fillProductDetailFields;fillProductDetailFields=function(p){baseFillProductDetailFields({...p,longDescription:p.longDescription||p.description});detailPhotos=[...(p.detailImages||[])];descriptionBlocks=Array.isArray(p.descriptionBlocks)?p.descriptionBlocks.map(b=>({text:b.text||'',image:b.image||'',layout:b.layout||'text-image'})):[];if(!Array.isArray(p.descriptionBlocks)&&((p.longDescription||p.description)||(p.detailImages||[]).length)){descriptionBlocks=[{text:p.longDescription||p.description||'',image:'',layout:'text'},...(p.detailImages||[]).map(image=>({text:'',image,layout:'image'}))]}window.__sosDescriptionBlocks=descriptionBlocks;renderDetailPhotos();renderDescriptionBlocks()};
document.addEventListener('click',event=>{const b=event.target.closest('[data-detail-photo-remove],[data-description-block-remove]');if(b?.dataset.detailPhotoRemove!==undefined){detailPhotos.splice(Number(b.dataset.detailPhotoRemove),1);renderDetailPhotos()}if(b?.dataset.descriptionBlockRemove!==undefined){if(busy)return;descriptionBlocks=readDescriptionBlocks(false);descriptionBlocks.splice(Number(b.dataset.descriptionBlockRemove),1);renderDescriptionBlocks()}});
document.addEventListener('click',event=>{if(event.target.id==='add-description-block'){descriptionBlocks=readDescriptionBlocks(false);descriptionBlocks.push({text:'',image:'',layout:'text-image'});renderDescriptionBlocks()}});
document.addEventListener('change',async event=>{const input=event.target;if(input.id==='detail-gallery-upload'&&input.files.length){const error=document.querySelector('#product-form .editor-error');const files=[...input.files];if(files.length+detailPhotos.length>12){error.textContent='Use até 12 imagens na descrição.';input.value='';return}if(files.some(f=>f.size>3145728)){error.textContent='Cada imagem deve ter no máximo 3 MB.';input.value='';return}lock(true);try{for(const file of files){const data=new FormData();data.append('image',file);const result=await api('/api/admin/upload',{method:'POST',body:data});detailPhotos.push(result.url);renderDetailPhotos()}error.textContent='Imagens enviadas. Clique em Salvar produto para aplicá-las.'}catch(e){error.textContent=e.message}finally{input.value='';lock(false)}return}const upload=input.dataset.descriptionUpload;if(upload===undefined||!input.files.length)return;const error=document.querySelector('#product-form .editor-error');const file=input.files[0];if(file.size>3145728){error.textContent='Cada imagem deve ter no máximo 3 MB.';input.value='';return}lock(true);try{const data=new FormData();data.append('image',file);const result=await api('/api/admin/upload',{method:'POST',body:data});descriptionBlocks[Number(upload)].image=result.url;renderDescriptionBlocks();error.textContent='Imagem enviada. Clique em Salvar produto para aplicá-la.'}catch(e){error.textContent=e.message}finally{input.value='';lock(false)}});

function readDescriptionBlocks(removeEmpty=true){const blocks=[...document.querySelectorAll('.description-block-row')].map(row=>({text:row.querySelector('[data-description-text]').value.trim(),image:row.querySelector('[data-description-image]').value.trim(),layout:row.querySelector('[data-description-layout]').value}));return removeEmpty?blocks.filter(b=>b.text||b.image):blocks}
document.addEventListener('input',event=>{if(event.target.closest('.description-block-row')){descriptionBlocks=readDescriptionBlocks(false);window.__sosDescriptionBlocks=descriptionBlocks}});
document.addEventListener('change',event=>{if(event.target.matches('[data-description-layout]')){descriptionBlocks=readDescriptionBlocks(false);window.__sosDescriptionBlocks=descriptionBlocks}});
